	prefixTerm, complete := pattern.LiteralPrefix()
	if complete {
		// there is no pattern
		candidateTerms = []string{prefixTerm}
	} else {
		var err error
		candidateTerms, err = findRegexpCandidateTerms(indexReader, pattern, field,
			prefixTerm)
