func ToPrecision(n, p float64) float64 {
	//credits http://stackoverflow.com/a/12055126/977939
	if n == 0 {
		return 0
	}
	e := math.Floor(math.Log10(math.Abs(n)))
	f := round(math.Exp(math.Abs(e-p+1) * log10))
	if e-p+1 < 0 {
		return round(n*f) / f
	}
	return round(n/f) * f
}

