func GraphToRanges(path []Edge) []TextRange {
	ranges := make([]TextRange, len(path))
	j := len(ranges) - 1
	for e := len(path) - 1; e > 0; {
		s := path[e].S
		ranges[j] = TextRange{s, e, path[e].EdgeType}
		j--
		e = s
	}
	return ranges[j+1:]
}

