func (fos *FanOutSink) Close() error {
	if fos.closed {
		return nil
	}

	fos.closed = true
	close(fos.stores)

	// wait for all workers to finish
	for i := 0; i < len(fos.sinks); i++ {
		err := <-fos.errs
		if err != nil {
			return err
		}
	}

	return nil
}

