func MultiAt3d(oct int, p, f, x, y, z float64) float64 {
	var (
		total        float64
		amplitude    float64 = 1.0
		maxAmplitude float64
	)

	for i := 0; i < oct; i++ {
		total += At3d(x*f, y*f, z*f) * amplitude
		f *= 2.0
		maxAmplitude += amplitude
		amplitude *= p
	}

	return total / maxAmplitude
}

