		var b bytes.Buffer
		if err := stats.Logf(&b, formatParams); err != nil {
			log.Errorf("Error formatting logStats: %v", err)
			continue
		}
		if err := writer.Info(b.String()); err != nil {
			log.Errorf("Error writing to syslog: %v", err)
			continue
		}
	}
