func (wg *WaitGroup) Until(callBack func(done chan struct{}) bool) {
	wg.mutex.Lock()
	if wg.done == nil {
		wg.done = make(chan struct{})
	}
	wg.mutex.Unlock()

	wg.wg.Add(1)
	go func() {
		for {
			if !callBack(wg.done) {
				wg.wg.Done()
				break
			}
		}
	}()
}

