func ReadAPI(fn string, m map[string][]string) error {
	f, err := os.Open(fn)
	if err != nil {
		return err
	}
	defer f.Close()

	scnr := bufio.NewScanner(f)
	var key string
	for scnr.Scan() {
		if s := scnr.Text(); strings.Contains(s, "//") {
			continue
		} else if strings.Contains(s, "\t") {
			m[key] = append(m[key], strings.Replace(s, "\t", "", -1))
			continue
		} else {
			m[s] = make([]string, 0)
			key = s
		}
	}
	return scnr.Err()
}

