	pipe := r.client.Pipeline()
	timeCmd := pipe.Time()
	getKeyCmd := pipe.Get(key)
	_, err := pipe.Exec()

	now, err := timeCmd.Result()
	if err != nil {
		return 0, now, err
	}

	v, err := getKeyCmd.Int64()
	if err == redis.Nil {
		return -1, now, nil
	} else if err != nil {
		return 0, now, err
	}

	return v, now, nil
}

