func (c *Conn) Wait(timeout int) error {
	done := make(chan bool)

	go func() { c.wg.Wait(); done <- true }()

	select {
	case <-done:
		return nil
	case <-time.After(time.Second * time.Duration(timeout)):
		return errors.New("wait timed out")
	}
}

